module.exports = /*#__PURE__*/JSON.parse('[{"id":"fundamentals","title":"Fundamentals","shortDescription":"Master the building blocks: variables, loops, control flow, functions, and memory basics.","difficulty":"Beginner","progress":100,"about":"Before tackling complex algorithms, you must build a flawless foundation. This level guides you through basic programming constructs, primitive types, memory allocations, and scoping, preparing your mind for computational thinking.","whatYouWillLearn":["Basic syntax & scoping rules","Memory structure: Stack vs Heap basics","Control flow, recursion, and iteration","Basic space and time analysis concepts"],"duration":"6 hours","modulesCount":4,"projectsCount":1,"certificateAvailable":true,"startUrl":"/learn/fundamentals/intro-to-programming"},{"id":"beginner-dsa","title":"Beginner DSA","shortDescription":"Get comfortable with linear data structures like Arrays, Linked Lists, Stacks, and Queues.","difficulty":"Easy","progress":85,"about":"Learn how data is organized sequentially in computer memory. Understand the trade-offs of contiguous versus node-based lists, and implement LIFO/FIFO patterns that form the backbone of modern runtime systems.","whatYouWillLearn":["Array allocations & dynamic resizing","Singly & Doubly Linked Lists","Stacks (LIFO) and Queues (FIFO) structures","Prefix Sums and Two-Pointer technique basics"],"duration":"12 hours","modulesCount":6,"projectsCount":2,"certificateAvailable":true,"startUrl":"/learn/beginner-dsa/intro"},{"id":"intermediate-dsa-1","title":"Intermediate DSA Level 1","shortDescription":"Explore asymptotic analysis, sorting algorithms, and binary search methodologies.","difficulty":"Medium","progress":50,"about":"Transition from simple coding to writing high-efficiency solutions. Learn how to quantify algorithm speeds using Big O notation, perform divide-and-conquer splits, and search sorted spaces instantly.","whatYouWillLearn":["Big-O, Big-Theta, and Big-Omega analysis","Classic sorting algorithms (Merge, Quick, Heap sort)","Binary Search on values and decision spaces","Hashing mechanisms and hash maps implementation"],"duration":"18 hours","modulesCount":8,"projectsCount":2,"certificateAvailable":true,"startUrl":"/learn/intermediate-dsa-1/intro"},{"id":"intermediate-dsa-2","title":"Intermediate DSA Level 2","shortDescription":"Dive into Trees, Binary Search Trees, Heaps, and priority queues.","difficulty":"Medium","progress":20,"about":"Hierarchical data representation is key for operating systems, databases, and searching. At this level, you\'ll master tree structures, learn traversal algorithms, and understand how to build efficient priority queues.","whatYouWillLearn":["Binary trees & depth-first/breadth-first traversals","Binary Search Trees (BST) properties & mutations","Max/Min Heap structures and heapifying algorithms","Priority Queues and their applications"],"duration":"20 hours","modulesCount":7,"projectsCount":2,"certificateAvailable":true,"startUrl":"/learn/intermediate-dsa-2/intro"},{"id":"advanced-dsa","title":"Advanced DSA","shortDescription":"Conquer Graphs, BFS/DFS traversal, Dijkstra\'s algorithm, and dynamic programming basics.","difficulty":"Hard","progress":0,"about":"Model interconnected systems using graphs. Learn pathfinding algorithms used by maps and routers, and explore the power of subproblem memoization to solve complex recursive optimizations.","whatYouWillLearn":["Graph representations: Adjacency list and matrix","Depth-First Search (DFS) & Breadth-First Search (BFS)","Shortest paths: Dijkstra, Bellman-Ford","Introduction to Dynamic Programming (1D & 2D tables)"],"duration":"30 hours","modulesCount":10,"projectsCount":3,"certificateAvailable":true,"startUrl":"/learn/advanced-dsa/intro"},{"id":"masters-dsa-1","title":"DSA Masters Level 1","shortDescription":"Master advanced recursion, backtracking, and complex Dynamic Programming patterns.","difficulty":"Hard","progress":0,"about":"Step into elite problem solving by mastering decision state generation and pruning. This level covers topological sorting, disjoint set union, and advanced optimization paradigms.","whatYouWillLearn":["State-space backtracking and constraint pruning","Topological sorting & strongly connected components","Disjoint Set Union (DSU) / Union-Find optimizations","Knapsack, LCS, and Matrix Chain DP patterns"],"duration":"25 hours","modulesCount":8,"projectsCount":3,"certificateAvailable":true,"startUrl":"/learn/masters-dsa-1/intro"},{"id":"masters-dsa-2","title":"DSA Masters Level 2","shortDescription":"Advanced string algorithms, Trie data structures, and segment trees.","difficulty":"Hard","progress":0,"about":"Implement query-efficient indexing for large-scale string and range data. Learn how search engines autocompleting queries and database range queries are optimized behind the scenes.","whatYouWillLearn":["Trie structures for dictionary indexing & routing","Segment Trees & Fenwick Trees (Binary Indexed Trees)","KMP (Knuth-Morris-Pratt) and Rabin-Karp pattern matching","Range Minimum Queries (RMQ) & Lazy propagation"],"duration":"28 hours","modulesCount":9,"projectsCount":3,"certificateAvailable":true,"startUrl":"/learn/masters-dsa-2/intro"},{"id":"masters-dsa-3","title":"DSA Masters Level 3","shortDescription":"Advanced graph topologies, network flow, and heuristic search algorithms.","difficulty":"Hard","progress":0,"about":"Push boundaries with network flow models, bipartite matching, and heuristics. Understand complex structural connectivity and flow bottlenecks.","whatYouWillLearn":["Ford-Fulkerson & Edmonds-Karp Max Flow","Bipartite matching and min-cut analysis","A* search & heuristic optimizations","Eulerian Paths and Hamiltonian cycles"],"duration":"32 hours","modulesCount":8,"projectsCount":4,"certificateAvailable":true,"startUrl":"/learn/masters-dsa-3/intro"},{"id":"dsa-demi-god","title":"DSA DEMI GOD","shortDescription":"The absolute peak. Approximate algorithms, randomized data structures, and cache-oblivious designs.","difficulty":"Legendary","progress":0,"about":"Achieve the status of a Demi God. Solve NP-hard approximations, learn randomized structures like Skip Lists, Bloom Filters, and implement cache-friendly designs optimized for physical hardware architecture.","whatYouWillLearn":["Randomized algorithms, Bloom filters, and Skip Lists","NP-Complete problem reduction & Approximation models","Cache-oblivious data structures (B-Trees, cache lines)","Advanced bit manipulation and hardware-level trickery"],"duration":"40 hours","modulesCount":12,"projectsCount":5,"certificateAvailable":true,"startUrl":"/learn/dsa-demi-god/intro"}]');

